  if (!Number.isFinite(sats) || sats <= 0) return null;
  if (!Number.isFinite(btcUsd) || btcUsd <= 0) return null;
  const usd = sats * btcUsd / 100_000_000;
  if (usd < 0.01) return '<$0.01';
  if (usd < 1)   return '$' + usd.toFixed(3).replace(/0+$/, '').replace(/\.$/, '');
