    amount:   entry.amount != null ? entry.amount.toString() : '',
    decimals: Number.isInteger(entry.decimals) ? entry.decimals : 0,
    assetId:  /^[0-9a-f]{64}$/.test(entry.assetId || '') ? entry.assetId : '',
