async function cancelPreauthBidVar({ assetIdHex, bidIdHex }) {
  await ensurePrivkey();
  if (!WORKER_BASE) throw new Error('worker disabled');
  if (!/^[0-9a-f]{64}$/.test(String(assetIdHex || ''))) throw new Error('asset_id must be 64-hex');
  if (!/^[0-9a-f]{32}$/.test(String(bidIdHex || ''))) throw new Error('bid_id must be 32-hex');
  const assetIdBytes = hexToBytes(assetIdHex);
  const bidIdBytes = hexToBytes(bidIdHex);
  const cancelMsg = _preauthBidVarCancelMsg(assetIdBytes, bidIdBytes);
  const cancelSig = signSchnorr(cancelMsg, wallet.priv);
  const resp = await fetch(withNet(PREAUTH_BID_VAR_URL(assetIdHex, bidIdHex)), {
    method: 'DELETE',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ cancel_sig: bytesToHex(cancelSig) }),
  });
  const j = await resp.json().catch(() => ({}));
  if (!resp.ok) throw new Error(j.error || `HTTP ${resp.status}`);
  try { invalidateMarketCache(); } catch {}
  try { _dropMyBidFromIndex(bidIdHex); } catch {}
  return j;
}

