async function _wtWalletUsed(addr) {
  const info = await apiJson(`/address/${addr}`);
  return ((info?.chain_stats?.tx_count || 0) + (info?.mempool_stats?.tx_count || 0)) > 0;
}
const _wtWalletClaimed = new Set();
