const _statusMirrors = new Map();
function addStatusMirror(primarySel, extraSel) {
  if (!_statusMirrors.has(primarySel)) _statusMirrors.set(primarySel, new Set());
  _statusMirrors.get(primarySel).add(extraSel);
}
function removeStatusMirror(primarySel, extraSel) {
  const s = _statusMirrors.get(primarySel);
  if (s) { s.delete(extraSel); if (s.size === 0) _statusMirrors.delete(primarySel); }
}
function setStatus(elOrSel, text, pending = false) {
  const el = typeof elOrSel === 'string' ? document.querySelector(elOrSel) : elOrSel;
  if (el) {
    el.textContent = text;
    el.classList.toggle('live-dots', !!pending && !!text);
  }
  if (typeof elOrSel === 'string') {
    const extras = _statusMirrors.get(elOrSel);
    if (extras) for (const extraSel of extras) {
      const ex = document.querySelector(extraSel);
      if (!ex) continue;
      ex.textContent = text;
      ex.classList.toggle('live-dots', !!pending && !!text);
    }
  }
}

const PROGRESS_STRIP_HTML = `
  <div class="progress-strip" style="display:none;margin-top:10px;" aria-live="polite">
    <div class="progress-step" data-step="0"><span class="progress-num">1</span><span class="progress-label">Build</span></div>
    <div class="progress-step" data-step="1"><span class="progress-num">2</span><span class="progress-label">Submit</span></div>
    <div class="progress-step" data-step="2"><span class="progress-num">3</span><span class="progress-label">Confirm</span></div>
    <div class="progress-step" data-step="3"><span class="progress-num">4</span><span class="progress-label">Pending</span></div>
  </div>
`;

const _BRIDGE_WITHDRAW_STEPS = [
  'withdrawing tETH to wallet',
  'building merkle proof',
  'verifying pool view matches on-chain SP1 state',
  'generating Groth16 proof',
  'proof:done',
  'building Bitcoin transaction',
  'broadcasting bridge export commit',
  'broadcasting bridge export reveal',
  'done',
];
const _BRIDGE_WITHDRAW_LABELS = {
  'withdrawing tETH to wallet':                     'Preparing withdrawal…',
  'building merkle proof':                          'Building merkle proof…',
  'verifying pool view matches on-chain SP1 state': 'Verifying pool state…',
  'generating Groth16 proof':                       'Generating ZK proof…',
  'proof:done':                                     'Proof generated ✓',
  'building Bitcoin transaction':                   'Building Bitcoin tx…',
  'broadcasting bridge export commit':              'Broadcasting commit…',
  'broadcasting bridge export reveal':              'Broadcasting reveal…',
  'done':                                           'tETH in your wallet ✓',
};

function _renderBridgeWithdrawProgress(statusEl, stage) {
  if (!statusEl) return;
  const label = _BRIDGE_WITHDRAW_LABELS[stage] || stage;
  const idx = _BRIDGE_WITHDRAW_STEPS.indexOf(stage);
  const pct = idx >= 0 ? Math.round(((idx + 1) / _BRIDGE_WITHDRAW_STEPS.length) * 100) : 0;
  const isProving = stage === 'generating Groth16 proof';
  const pulse = isProving ? 'animation:bridge-pulse 2s ease-in-out infinite;' : '';
  const bar = pct > 0
    ? `<div style="background:var(--ink-faint);border-radius:4px;height:6px;margin:8px 0 4px;overflow:hidden;"><div style="background:#627eea;height:100%;width:${isProving ? '60' : pct}%;transition:width 0.5s;${pulse}"></div></div>`
    : '';
  statusEl.innerHTML = `${escapeHtml(label)}${bar}`;
  statusEl.style.color = stage === 'done' ? 'var(--green)' : '';
}

async function _runBridgeAccelerate({ noteRecord, btn, statusEl, onDone } = {}) {
  if (btn) { btn.disabled = true; }
  const origLabel = btn ? btn.textContent : '';
  if (statusEl) { statusEl.style.display = ''; _renderBridgeWithdrawProgress(statusEl, 'withdrawing tETH to wallet'); }
  try {
    const result = await bridgeAutoWithdraw({
      noteRecord,
      onProgress: (stage) => {
        if (statusEl) _renderBridgeWithdrawProgress(statusEl, stage);
        if (btn) {
          const label = _BRIDGE_WITHDRAW_LABELS[stage] || stage;
          btn.textContent = label.length > 22 ? 'Working…' : label;
        }
      },
    });
    if (btn) { btn.textContent = 'Withdrawn ✓'; btn.style.background = 'var(--green)'; btn.style.borderColor = 'var(--green)'; btn.style.color = '#fff'; }
    if (statusEl) _renderBridgeWithdrawProgress(statusEl, 'done');
    try { onDone?.(result); } catch {}
    return result;
  } catch (e) {
    if (btn) { btn.textContent = origLabel; btn.disabled = false; }
    if (statusEl) { statusEl.innerHTML = `Accelerate failed: ${escapeHtml(String(e?.message || e))}`; statusEl.style.color = 'var(--red)'; }
    throw e;
  }
}

function _renderBridgeModalPendingWithdrawals() {
  const modal = document.getElementById('bridge-modal');
  if (!modal) return;
  const opts = modal.querySelector('.welcome-options');
  if (!opts) return;
  const existing = opts.querySelector('[data-bridge-modal-pending]');
  if (existing) existing.remove();

  let unspent = [];
  try { unspent = _gatherUnspentBridgeNotes(); } catch {}
  if (!unspent.length) return;

  const ready = unspent.filter(n => !n.autoWithdrawPending && _bridgeNoteLeafReady(n));
  const confirming = unspent.filter(n => !(!n.autoWithdrawPending && _bridgeNoteLeafReady(n)));
  const totalAmt = unspent.reduce((s, n) => s + BigInt(n.denomination || 0), 0n);
  const headline = ready.length
    ? `${unspent.length} pool note${unspent.length > 1 ? 's' : ''} ready. Accelerate to withdraw into a spendable tETH in your wallet.`
    : `${confirming.length} pool note${confirming.length > 1 ? 's' : ''} confirming on Bitcoin — not spendable until the deposit is mined + proven. Funds are safe.`;
  const wrap = document.createElement('div');
  wrap.setAttribute('data-bridge-modal-pending', '');
  wrap.style.cssText = 'margin-bottom:12px;padding:12px;border:1px solid #627eea;border-radius:6px;background:rgba(98,126,234,0.05);';
  wrap.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
      <div style="flex:1;min-width:0;">
        <div style="font-size:12px;font-weight:600;display:flex;align-items:center;gap:5px;"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 32 32" width="16" height="16"><circle cx="16" cy="16" r="13" fill="none" stroke="#627eea" stroke-width="2.5"/><path d="M17.5 7L13 22.5Q13 25 18 24" fill="none" stroke="#627eea" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/><path d="M10 11L21 11" stroke="#627eea" stroke-width="2.4" stroke-linecap="round"/><path d="M14.8 17L19 17" stroke="#627eea" stroke-width="2.2" stroke-linecap="round"/></svg> ${escapeHtml(fmtAssetAmount(totalAmt, 8))} tETH ${ready.length ? 'in mixer pool' : 'confirming in mixer pool'}</div>
        <div class="muted" style="font-size:10px;margin-top:2px;line-height:1.5;">${headline}</div>
      </div>
      ${ready.length ? '<button type="button" data-bridge-modal-accel style="font-size:11px;padding:6px 12px;white-space:nowrap;background:transparent;border:1px solid #627eea;color:#627eea;">Accelerate to wallet</button>' : ''}
    </div>
    <div class="muted" data-bridge-accel-status style="display:none;font-size:11px;line-height:1.5;margin-top:8px;"></div>
  `;
  opts.insertBefore(wrap, opts.firstChild);

  const accelBtn = wrap.querySelector('[data-bridge-modal-accel]');
  const statusEl = wrap.querySelector('[data-bridge-accel-status]');
  accelBtn?.addEventListener('click', async () => {
    try {
      await _runBridgeAccelerate({
        noteRecord: ready[0],
        btn: accelBtn,
        statusEl,
        onDone: () => {
          toast('tETH accelerated to wallet — check Holdings.', 'success');
          setTimeout(() => { try { _renderBridgeModalPendingWithdrawals(); } catch {} try { renderHoldings(); } catch {} try { renderPool(); } catch {} }, 2000);
        },
      });
    } catch (err) {
      toast('Accelerate failed: ' + (err?.message || err), 'error', 6000);
    }
  });
}

function applyOptimisticDebit(assetIdHex, delta) {
  const cards = document.querySelectorAll('#holdings-list > .asset-card');
  let card = null;
  for (const c of cards) {
    if (c.dataset.aid === assetIdHex) { card = c; break; }
  }
  if (!card) return;
  const balanceEl = card.querySelector('.balance');
  if (!balanceEl) return;
  const baseAttr = card.dataset.baseAmount;
  const decAttr = card.dataset.decimals;
  if (!baseAttr || decAttr === undefined) return;
  let prev;
  try { prev = BigInt(baseAttr); }
  catch { return; }
  const dec = parseInt(decAttr, 10);
  if (!Number.isInteger(dec)) return;
  const next = prev > delta ? prev - delta : 0n;
  card.dataset.baseAmount = next.toString();
  const firstTextNode = balanceEl.firstChild;
  if (firstTextNode && firstTextNode.nodeType === Node.TEXT_NODE) {
    firstTextNode.textContent = fmtAssetAmount(next, dec);
  }
  let pill = card.querySelector('[data-optimistic-pending]');
  const prevDebitAttr = card.dataset.optimisticDebit || '0';
  let prevDebit;
  try { prevDebit = BigInt(prevDebitAttr); }
  catch { prevDebit = 0n; }
  const totalDebit = prevDebit + delta;
  card.dataset.optimisticDebit = totalDebit.toString();
  const fmtTotal = fmtAssetAmount(totalDebit, dec);
  if (!pill) {
    pill = document.createElement('span');
    pill.setAttribute('data-optimistic-pending', '1');
    pill.className = 'pending-pill';
    balanceEl.appendChild(pill);
  }
  pill.textContent = `settling −${fmtTotal}`;
}

const PRICE_ALERTS_KEY = 'tacit-price-alerts-v1';
const PRICE_ALERTS_POLL_MS = 60_000;
let _priceAlerts = (() => {
  try {
    const raw = localStorage.getItem(PRICE_ALERTS_KEY);
    if (!raw) return [];
    const arr = JSON.parse(raw);
    return Array.isArray(arr) ? arr.filter(a => a && a.aid && Number.isFinite(a.threshold_unit) && (a.direction === 'above' || a.direction === 'below')) : [];
  } catch { return []; }
})();
let _priceAlertsTimer = null;
function _priceAlertsPersist() {
  try { localStorage.setItem(PRICE_ALERTS_KEY, JSON.stringify(_priceAlerts)); } catch {}
}
function _priceAlertsRemove(id) {
  const before = _priceAlerts.length;
  _priceAlerts = _priceAlerts.filter(a => a.id !== id);
  if (_priceAlerts.length !== before) _priceAlertsPersist();
}
async function _priceAlertsPollOnce() {
  if (typeof document !== 'undefined' && document.hidden) return;
  if (_priceAlerts.length === 0) return;
  const byAid = new Map();
  for (const a of _priceAlerts) {
    if (!byAid.has(a.aid)) byAid.set(a.aid, []);
    byAid.get(a.aid).push(a);
  }
  const _fmt = (u, ticker) => `${fmtUnitPriceSats(u)} sats/${ticker}`;
  for (const [aid, alerts] of byAid) {
    if (!WORKER_BASE) continue;
    let markUnit = null;
    let ticker = alerts[0]?.ticker || aid.slice(0, 6);
    try {
      const j = await apiJson(`/assets/${aid}`);
      const u = Number(j?.mark_price?.unit);
      if (Number.isFinite(u) && u > 0) markUnit = u;
      if (j?.ticker) ticker = j.ticker;
    } catch {}
    if (markUnit == null) continue;
    const toRemove = [];
    for (const a of alerts) {
      const triggered = (a.direction === 'above' && markUnit >= a.threshold_unit) ||
                        (a.direction === 'below' && markUnit <= a.threshold_unit);
      if (!triggered) continue;
      toRemove.push(a.id);
      const arrow = a.direction === 'above' ? '↑' : '↓';
      toast(`🔔 ${ticker} ${arrow} · crossed ${_fmt(a.threshold_unit, ticker)} (now ${_fmt(markUnit, ticker)})`, 'success', 12000);
    }
    for (const id of toRemove) _priceAlertsRemove(id);
  }
}
function _startPriceAlertsLoop() {
  if (_priceAlertsTimer) return;
  _priceAlertsPollOnce();
  _priceAlertsTimer = setInterval(_priceAlertsPollOnce, PRICE_ALERTS_POLL_MS);
  if (typeof document !== 'undefined') {
    document.addEventListener('visibilitychange', () => { if (!document.hidden) _priceAlertsPollOnce(); });
  }
}
if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _startPriceAlertsLoop);
  else _startPriceAlertsLoop();
}



