  c.mints[mintTxid] = { ...entry, ts: Date.now() };
  if (Object.keys(c.mints).length > DISCOVER_CACHE_MAX_TXVERS * 1.2) _evictDiscoverCacheOldest();
  _scheduleDiscoverCacheFlush();
