const MARKET_PRUNE_CONCURRENCY = 3;
function startMarketLivenessPrune() {
  if (!_marketCache) return;
  const grid = $('#market-list');
  if (!grid) return;
  const queue = [];
  for (const l of _marketCache.listings.slice()) {
    let txid, vout;
    if (l.kind === 'opening') { txid = l.txid; vout = l.vout | 0; }
    else if (l.kind === 'intent') { txid = l.asset_utxo?.txid; vout = l.asset_utxo?.vout | 0; }
    else if (l.kind === 'preauth') { txid = l.asset_outpoint?.txid; vout = l.asset_outpoint?.vout | 0; }
    else continue;
    if (!txid) continue;
    queue.push({ l, txid, vout });
  }
  let active = 0;
  let i = 0;
  const _invalidateLiveCaches = () => {
    _marketFloorCache = { src: null, map: null };
    _marketLiveCountCache = { src: null, map: null };
    _marketMarkCache = { src: null, map: null };
  };
  const onSpent = (l) => {
    if (_marketCache) {
      _marketCache.listings = _marketCache.listings.filter(x => x !== l);
    }
    if (_marketView === 'browse') {
      _scheduleMarketPruneRender();
      return;
    }
    const key = l.kind === 'opening' ? `opening:${l.txid}:${l.vout | 0}`
              : l.kind === 'preauth' ? `preauth:${l.sale_id}`
              : `intent:${l.intent_id}`;
    const tile = grid.querySelector(`[data-listing-key="${CSS.escape(key)}"]`);
    if (!tile) return;
    tile.remove();
  };
  const onTakenPending = (l) => {
    if (l._takenPending) return;
    l._takenPending = true;
    l._takenPendingAt = Date.now();
    _invalidateLiveCaches();
    if (_marketView === 'browse') { _scheduleMarketPruneRender(); return; }
    try {
      const key = l.kind === 'opening' ? `opening:${l.txid}:${l.vout | 0}`
                : l.kind === 'preauth' ? `preauth:${l.sale_id}`
                : `intent:${l.intent_id}`;
      const tile = grid.querySelector(`[data-listing-key="${CSS.escape(key)}"]`);
      if (tile) tile.dataset.takenPending = '1';
    } catch {}
  };
  const onUnspentRecover = (l) => {
    if (!l._takenPending) return;
    l._takenPending = false;
    l._takenPendingAt = 0;
    _invalidateLiveCaches();
    if (_marketView === 'browse') { _scheduleMarketPruneRender(); return; }
    try {
      const key = l.kind === 'opening' ? `opening:${l.txid}:${l.vout | 0}`
                : l.kind === 'preauth' ? `preauth:${l.sale_id}`
                : `intent:${l.intent_id}`;
      const tile = grid.querySelector(`[data-listing-key="${CSS.escape(key)}"]`);
      if (tile) delete tile.dataset.takenPending;
    } catch {}
  };
  const drain = () => {
    while (active < MARKET_PRUNE_CONCURRENCY && i < queue.length) {
      const { l, txid, vout } = queue[i++];
      active++;
      getOutspend(txid, vout).then((sp) => {
        if (sp && sp.spent) {
          if (sp.status && sp.status.confirmed === true) onSpent(l);
          else onTakenPending(l);
        } else {
          onUnspentRecover(l);
        }
      }).catch(() => {}).finally(() => {
        active--;
        drain();
      });
    }
  };
  drain();
}

const MARKET_FETCH_TTL_MS = 30 * 1000;
let _marketFetchedAt = 0;
let _marketFetchInFlight = null;
async function fetchMarketDataDeduped() {
  if (_marketCache && (Date.now() - _marketFetchedAt) < MARKET_FETCH_TTL_MS) {
    return _marketCache;
  }
  if (_marketFetchInFlight) return _marketFetchInFlight;
  _marketFetchInFlight = fetchMarketData()
    .then(data => {
      if (data) {
        _marketCache = data;
        _marketFetchedAt = Date.now();
        try { _renderGlobalTape(); } catch {}
      }
      _marketFetchInFlight = null;
      return data;
    })
    .catch(e => {
      _marketFetchInFlight = null;
      throw e;
    });
  return _marketFetchInFlight;
}
function invalidateMarketCache() { _marketFetchedAt = 0; }

