    if (l.kind !== 'preauth' || nonceHex.length !== 32) return null;
    const seed = nonceHex.slice(0, 16);
    const aid = l._asset?.asset_id || l.asset_id || '';
    const amt = (l.asset_opening?.amount ?? '') + '';
