function refreshYourOpenOrdersPanel(scope, aid) {
  if (!scope || !aid) return;
  const panel = scope.querySelector(`[data-your-orders][data-aid="${aid}"]`);
  if (!panel) return;
  const myPubHex = panel.dataset.pub || ((wallet && wallet.pub) ? bytesToHex(wallet.pub) : '');
  const assetForBids = (_marketCache?.listings?.find(l => l._asset?.asset_id === aid)?._asset)
    || (_marketCache?.assets?.find(x => x.asset_id === aid))
    || { asset_id: aid, ticker: '?', decimals: 0 };
  const fresh = renderYourOpenOrdersHTML(aid, assetForBids, myPubHex);
  if (!fresh) {
    panel.remove();
    return;
  }
  const tmp = document.createElement('div');
  tmp.innerHTML = fresh.trim();
  const next = tmp.firstElementChild;
  if (!next) return;
  panel.replaceWith(next);
  next.querySelectorAll('button[data-act="your-orders-cancel-ask"]').forEach(btn => {
    btn.onclick = async () => marketCancelPreauthHandler(btn);
  });
  next.querySelectorAll('button[data-act="your-orders-cancel-ask-group"]').forEach(btn => {
    btn.onclick = async () => marketCancelPreauthGroupHandler(btn);
  });
  next.querySelectorAll('button[data-act="your-orders-cancel-intent"]').forEach(btn => {
    btn.onclick = async () => marketCancelIntentHandler(btn);
  });
  next.querySelectorAll('button[data-act="your-orders-cancel-bid"]').forEach(btn => {
    btn.onclick = async () => {
      if (btn.disabled) return;
      if (!confirm('Cancel this bid? Removes it from the book so no new seller can match it — but if a seller had already started filling it in the last few seconds, that fill can still complete.')) return;
      const aidc = btn.dataset.aid;
      const bidId = btn.dataset.bidId;
      btn.disabled = true; const orig = btn.textContent; btn.textContent = 'cancelling…';
      try {
        await cancelBidIntent(aidc, bidId);
        toast('Bid cancelled ✓', 'success');
        _invalidateBidsCache(aidc);
        setTimeout(() => renderMarket(), 500);
      } catch (e) {
        btn.disabled = false; btn.textContent = orig;
        if (isUnlockCancelled(e)) toast('Unlock cancelled — nothing was removed.', '');
        else toast('Cancel failed: ' + (e?.message || String(e)), 'error');
      }
    };
  });
  next.querySelectorAll('button[data-act="your-orders-bid-take-instead"]').forEach(btn => {
    btn.onclick = async () => _bidTakeInsteadHandler(btn);
  });
  next.querySelectorAll('button[data-act="your-orders-improve-bid"]').forEach(btn => {
    btn.onclick = async () => _improveBidHandler(btn);
  });
  next.querySelectorAll('button[data-act="your-orders-cancel-all"]').forEach(btn => {
    btn.onclick = async () => _cancelAllOrdersHandler(btn);
  });
}

function _previewBidTakeRoute(aid, decimals, bidUnit, satsBudget, myPubHex) {
  const nowSec = Math.floor(Date.now() / 1000);
  const candidates = [];
  for (const l of (_marketCache?.listings || [])) {
    if (l._asset?.asset_id !== aid) continue;
    if (l.kind !== 'preauth') continue;
    if (l.expired || Number(l.expiry || 0) <= nowSec) continue;
    if (l._takenPending) continue;
    if (l.seller_pubkey === myPubHex) continue;
    const amt = BigInt(l.asset_opening?.amount || 0);
    const ps = Number(l.min_price_sats || 0);
    if (amt <= 0n || ps <= 0) continue;
    const u = unitPriceSats(ps, amt, decimals);
    if (!Number.isFinite(u) || u <= 0 || u > bidUnit) continue;
    candidates.push({ l, amt, ps, u });
  }
  candidates.sort((a, b) => a.u - b.u);
  const plan = [];
  let totalSats = 0; let totalAmt = 0n;
  for (const c of candidates) {
    if (totalSats + c.ps > satsBudget) continue;
    plan.push(c);
    totalSats += c.ps;
    totalAmt += c.amt;
  }
  return plan.length > 0 ? { plan, totalSats, totalAmt } : null;
}

async function _improveBidHandler(btn) {
  if (!btn || btn.disabled) return;
  const aid = btn.dataset.aid;
  const bidId = btn.dataset.bidId;
  const targetUnit = Number(btn.dataset.targetUnit || '0');
  const bidAmtBase = btn.dataset.bidAmtBase || '0';
  const currentSats = Number(btn.dataset.currentSats || '0');
  if (!aid || !bidId || !(targetUnit > 0) || bidAmtBase === '0') {
    toast('Improve: missing inputs (refresh the page and retry).', 'error');
    return;
  }
  const asset = (_marketCache?.assets || []).find(a => a.asset_id === aid)
    || (_marketCache?.listings || []).find(l => l._asset?.asset_id === aid)?._asset
    || null;
  const decimals = Number.isInteger(asset?.decimals) ? asset.decimals : 0;
  const ticker = asset?.ticker || '?';
  const bidAmt = (() => { try { return BigInt(bidAmtBase); } catch { return 0n; } })();
  if (bidAmt <= 0n) { toast('Improve: invalid bid amount.', 'error'); return; }
  const newPriceSats = Math.max(DUST, Math.ceil(targetUnit * Number(bidAmt) / Math.pow(10, decimals)));
  const _diffSats = newPriceSats - currentSats;
  const _proceed = await tacitConfirm({
    title: `Improve bid to #1 — ${fmtUnitPriceSats(targetUnit)} sats/${ticker}?`,
    body:
      `Atomic two-step:\n` +
      `  1. Cancel your current bid (${currentSats.toLocaleString()} sats, signed off-chain, no fee)\n` +
      `  2. Post a new bid at ${fmtUnitPriceSats(targetUnit)} sats/${ticker} for ${fmtAssetAmount(bidAmt, decimals)} ${ticker} (${newPriceSats.toLocaleString()} sats, ${_diffSats >= 0 ? '+' : ''}${_diffSats.toLocaleString()} from current)\n\n` +
      `Jumps you to #1 in the bid ladder. Same amount of ${ticker}, slightly higher price per token.\n\n` +
      `If step 2 fails after step 1 succeeds, your bid is gone but your sats are intact — re-bid manually via Advanced or another Swap.`,
    confirmLabel: `Improve to #1 (${_diffSats >= 0 ? '+' : ''}${_diffSats.toLocaleString()} sats)`,
  });
  if (!_proceed) return;
  btn.disabled = true; const _origLabel = btn.textContent; btn.textContent = 'improving…';
  let _cancelled = false;
  try {
    await cancelBidIntent(aid, bidId);
    _cancelled = true;
    const _improveResult = await _postBidPreferVar({
      assetIdHex: aid,
      amount: bidAmt,
      priceSats: newPriceSats,
      expiry: Math.floor(Date.now() / 1000) + 24 * 3600,
      decimals,
    });
    const _improveSuffix = _improveResult.via === 'preauth-bid-var' ? ' · walk-away (close the tab safely)' : '';
    toast(
      `Bid improved · now ${fmtAssetAmount(bidAmt, decimals)} ${ticker} @ ${fmtUnitPriceSats(targetUnit)} sats/${ticker} for ${newPriceSats.toLocaleString()} sats · #1 in ladder${_improveSuffix}.`,
      'success', 9000,
    );
  } catch (e) {
    if (isUnlockCancelled(e)) {
      toast(_cancelled
        ? `Cancel succeeded; new bid was unlock-cancelled. Your sats are intact; re-bid manually if you want a position.`
        : 'Unlock cancelled — bid unchanged.',
        '', 10000,
      );
    } else {
      toast(
        _cancelled
          ? `Improve failed at re-post (${e?.message || String(e)}). Your bid was cancelled but the new bid didn't land — sats intact, re-bid manually.`
          : `Improve failed: ${e?.message || String(e)}`,
        'error', 12000,
      );
    }
  } finally {
    btn.disabled = false; btn.textContent = _origLabel;
  }
}



