let _unisatHooked = false;
function setupUnisatEvents() {
  if (_unisatHooked) return;
  if (!window.unisat || typeof window.unisat.on !== 'function') return;
  _unisatHooked = true;

  window.unisat.on('accountsChanged', async (accounts) => {
    if (!extWallet.state || extWallet.state.provider !== 'unisat') return;
    if (!accounts || !accounts.length) {
      applyExtDisconnect();
      toast('UniSat signed out — using the in-page wallet only', '');
      return;
    }
    if (accounts[0] === extWallet.state.address) return;
    try {
      const st = await extWallet.connectUnisat();
      if (reconcileWalletNetwork(st) !== 'ok') return;
      await rebindToExt();
      toast('UniSat account switched', 'success');
    } catch (e) {
      toast('Account switch failed: ' + e.message, 'error');
    }
  });

  window.unisat.on('networkChanged', (network) => {
    if (!extWallet.state || extWallet.state.provider !== 'unisat') return;
    extWallet.state = { ...extWallet.state, network };
    _cacheExtState(extWallet.state);
    reconcileWalletNetwork(extWallet.state);
  });
}

function setupHoldingsButtons() {
  $('#btn-rescan').onclick = async () => {
    try { await bridgeRecoverNotes(); } catch {}
    renderHoldings();
  };
  $('#btn-holdings-markets')?.addEventListener('click', () => {
    const tab = $('.tab[data-tab="market"]');
    if (tab) tab.click();
  });
  $('#btn-import-share').onclick = (e) => {
    openInlineForm(e.currentTarget, {
      submitLabel: 'Import',
      content: `
        <label>Share-link URL</label>
        <textarea data-field="link" rows="2" style="font-family:var(--mono);font-size:11px;padding:8px;border:1px solid var(--ink);background:var(--bg);width:100%;resize:vertical;" placeholder="https://…/#recv=…"></textarea>
        <div class="muted" style="margin-top:6px;font-size:11px;">
          Paste a share-link sent to you. The dapp validates the claim against on-chain data before recording an opening.
        </div>`,
      onSubmit: async ({ host, errEl }) => {
        const link = host.querySelector('[data-field="link"]').value.trim();
        if (!link) { errEl.textContent = 'paste a share-link'; return false; }
        if (!link.includes('#recv=')) { errEl.textContent = 'link must contain a #recv= fragment'; return false; }
        const data = await importShareLink(link);
        toast(`Imported ${fmtAssetAmount(data.amount, data.decimals)} ${data.ticker}`, 'success');
        markOnboarded();
        renderHoldings();
      },
    });
  };
  $('#btn-take-atomic')?.addEventListener('click', (e) => {
    openInlineForm(e.currentTarget, {
      submitLabel: 'Validate offer',
      content: `
        <label>Atomic offer (JSON pasted from the maker)</label>
        <textarea data-field="offer" rows="4" style="font-family:var(--mono);font-size:11px;padding:8px;border:1px solid var(--ink);background:var(--bg);width:100%;resize:vertical;" placeholder='{"version":1,"asset_id":"…",…}'></textarea>
        <div class="muted" style="margin-top:6px;font-size:11px;">
          Settles atomically in one Bitcoin tx: you pay the maker's address, you receive the tacit UTXO. No counterparty trust required — the maker's sigs are SIGHASH_SINGLE_ACP, so they can't redirect your payment, and the kernel sig is bound to the on-chain commitments.
        </div>`,
      onSubmit: async ({ host, errEl }) => {
        const raw = host.querySelector('[data-field="offer"]').value.trim();
        if (!raw) { errEl.textContent = 'paste an offer'; return false; }
        let offer;
        try { offer = JSON.parse(raw); }
        catch (e2) { errEl.textContent = 'invalid JSON: ' + e2.message; return false; }
        try { verifyAxferOffer(offer); }
        catch (e2) { errEl.textContent = 'offer rejected: ' + e2.message; return false; }
        const review = atomicOfferReview(offer);
        if (review.error) { errEl.textContent = review.error; return false; }
        if (!confirm(review.text)) return false;
        try {
          const r = await takeAxferOffer({ ...offer, ticker: review.ticker, decimals: review.decimals });
          toast(`Atomic take broadcast ✓ tx=${shorten(r.txid, 8)}`, 'success', 8000);
          renderHoldings(); renderActivity();
        } catch (e2) {
          errEl.textContent = e2.message;
          return false;
        }
      },
    });
  });
}

let _discoverPill = 'all';
let _discoverSort = 'newest';
let _petchPill = 'all';
let _petchSort = 'newest';
let _discoverEtcherMap = new Map();
function _discoverRegisterEtcher(etcherXonly, assetId) {
  if (!etcherXonly || !assetId) return;
  if (!_discoverEtcherMap.has(etcherXonly)) _discoverEtcherMap.set(etcherXonly, new Set());
  _discoverEtcherMap.get(etcherXonly).add(assetId);
}
function _matchesPill(card) {
  switch (_discoverPill) {
    case 'mintable': return card.dataset.mintable === '1';
    case 'attested': return card.dataset.attested === '1';
    case 'verified': return card.dataset.verified === '1';
    case 'recent': {
      const t = Number(card.dataset.etchedAt) || 0;
      if (!t) return false;
      return t * 1000 >= Date.now() - 24 * 3600 * 1000;
    }
    case 'offers':   return card.dataset.hasOffers === '1';
    case 'atomic':   return card.dataset.hasAtomic === '1';
    case 'burned':   return card.dataset.hasBurns === '1';
    case 'moved':    return card.dataset.hasTransfers === '1';
    default: return true;
  }
}

function applyDiscoverSort() {
  const list = $('#discover-list');
  if (!list) return;
  const cards = Array.from(list.querySelectorAll('.asset-card[data-aid]'));
  if (cards.length < 2) return;
  const _sameTimeTiebreak = (a, b, descending) => {
    const at = Number(a.dataset.txIndex), bt = Number(b.dataset.txIndex);
    if (Number.isFinite(at) && Number.isFinite(bt) && at !== bt) {
      return descending ? bt - at : at - bt;
    }
    return (a.dataset.aid || '').localeCompare(b.dataset.aid || '');
  };
  const tieByRecency = (a, b) => {
    const d = (Number(b.dataset.etchedAt) || 0) - (Number(a.dataset.etchedAt) || 0);
    return d !== 0 ? d : _sameTimeTiebreak(a, b, true);
  };
  const numDesc = (key) => (a, b) => {
    const d = (Number(b.dataset[key]) || 0) - (Number(a.dataset[key]) || 0);
    return d !== 0 ? d : tieByRecency(a, b);
  };
  cards.sort((a, b) => {
    switch (_discoverSort) {
      case 'newest':         return tieByRecency(a, b);
      case 'ticker-asc':     return (a.dataset.ticker || '').localeCompare(b.dataset.ticker || '');
      case 'ticker-desc':    return (b.dataset.ticker || '').localeCompare(a.dataset.ticker || '');
      case 'active-desc':    return numDesc('activityCount')(a, b);
      case 'oldest':
      default: {
        const d = (Number(a.dataset.etchedAt) || 0) - (Number(b.dataset.etchedAt) || 0);
        return d !== 0 ? d : _sameTimeTiebreak(a, b, false);
      }
    }
  });
  for (const c of cards) list.appendChild(c);
}
let _applyDiscoverFilterScheduled = false;
function _scheduleApplyDiscoverFilter() {
  if (_applyDiscoverFilterScheduled) return;
  _applyDiscoverFilterScheduled = true;
  requestAnimationFrame(() => {
    _applyDiscoverFilterScheduled = false;
    try { applyDiscoverFilter(); } catch {}
  });
}

function applyDiscoverFilter() {
  const input = $('#discover-filter');
  const list = $('#discover-list');
  if (!input || !list) return;
  let q = input.value.trim().toLowerCase();
  if (q.startsWith('0x')) q = q.slice(2);
  q = q.replace(/^["']|["']$/g, '').replace(/\s+/g, ' ');
  const cards = list.querySelectorAll('.asset-card[data-filter-key]');
  let visible = 0;
  cards.forEach(card => {
    const matchQ = !q || card.dataset.filterKey.includes(q);
    const matchP = _matchesPill(card);
    const match = matchQ && matchP;
    card.style.display = match ? '' : 'none';
    if (match) visible++;
  });
  let emptyHint = list.querySelector('[data-filter-empty]');
  const filterActive = q || _discoverPill !== 'all';
  if (filterActive && cards.length > 0 && visible === 0) {
    if (!emptyHint) {
      emptyHint = document.createElement('div');
      emptyHint.dataset.filterEmpty = '1';
      emptyHint.className = 'empty';
      emptyHint.style.marginTop = '12px';
      list.appendChild(emptyHint);
    }
    const pillBtn = _discoverPill === 'all'
      ? null
      : document.querySelector(`#discover-pills .filter-pill[data-pill="${CSS.escape(_discoverPill)}"]`);
    const pillName = pillBtn?.textContent?.trim().toLowerCase() || _discoverPill;
    const pillLabel = _discoverPill === 'all' ? '' : ` (${pillName})`;
    emptyHint.textContent = q
      ? `No assets match "${q}"${pillLabel}.`
      : `No ${pillName} assets.`;
  } else if (emptyHint) {
    emptyHint.remove();
  }
  const petchList = $('#petch-discover-list');
  if (petchList) {
    const petchCards = petchList.querySelectorAll('.asset-card[data-filter-key]');
    let petchVisible = 0;
    petchCards.forEach(card => {
      const matchQ = !q || card.dataset.filterKey.includes(q);
      const matchP = _petchPill === 'all' || card.dataset.petchStatus === _petchPill;
      const match = matchQ && matchP;
      card.style.display = match ? '' : 'none';
      if (match) petchVisible++;
    });
    const petchStatus = $('#petch-discover-status');
    if (petchStatus && (q || _petchPill !== 'all') && petchCards.length > 0) {
      setStatus(petchStatus, `${petchVisible} of ${petchCards.length} matching`);
    }
    let petchEmpty = petchList.querySelector('[data-filter-empty]');
    const petchActive = q || _petchPill !== 'all';
    if (petchActive && petchCards.length > 0 && petchVisible === 0) {
      if (!petchEmpty) {
        petchEmpty = document.createElement('div');
        petchEmpty.dataset.filterEmpty = '1';
        petchEmpty.className = 'empty';
        petchEmpty.style.marginTop = '12px';
        petchList.appendChild(petchEmpty);
      }
      const pillLabel = _petchPill === 'all' ? '' : ` (${_petchPill})`;
      petchEmpty.textContent = q
        ? `No public mints match "${q}"${pillLabel}.`
        : `No ${_petchPill} public mints.`;
    } else if (petchEmpty) {
      petchEmpty.remove();
    }
  }
}

const _PREFS_DISCOVER_KEY = (net) => `tacit-discover-prefs:${net}`;
const _PREFS_MARKET_KEY = (net) => `tacit-market-prefs:${net}`;
function _saveDiscoverPrefs() {
  try {
    localStorage.setItem(_PREFS_DISCOVER_KEY(NET.name), JSON.stringify({
      sort: _discoverSort,
      pill: _discoverPill,
      petchSort: _petchSort,
      petchPill: _petchPill,
    }));
  } catch { }
}
function _loadDiscoverPrefs() {
  try {
    const raw = localStorage.getItem(_PREFS_DISCOVER_KEY(NET.name));
    if (!raw) return null;
    const o = JSON.parse(raw);
    return (o && typeof o === 'object') ? o : null;
  } catch { return null; }
}
function _marketDefaultPrefs(scope) {
  return scope === 'asset'
    ? { kind: 'all', min: '', max: '', sort: 'unit-asc' }
    : { kind: 'all', min: '', max: '', sort: 'marketcap-desc' };
}
function _validSelectValue(sel, value) {
  const el = $(sel);
  return !!(el && typeof value === 'string' && Array.from(el.options).some(o => o.value === value));
}
function _normaliseMarketPrefs(o) {
  const out = {
    version: 4,
    browse: _marketDefaultPrefs('browse'),
    asset: _marketDefaultPrefs('asset'),
  };
  if (!o || typeof o !== 'object') return out;
  if (!o.browse && !o.asset) {
    out.browse = {
      ...out.browse,
      kind: _validSelectValue('#market-filter-kind', o.kind) && o.kind !== 'all' ? o.kind : out.browse.kind,
      min: typeof o.min === 'string' ? o.min : '',
      max: typeof o.max === 'string' ? o.max : '',
      sort: _validSelectValue('#market-sort', o.sort) && o.sort !== 'unit-asc' ? o.sort : out.browse.sort,
    };
    out.asset = {
      ...out.asset,
      kind: _validSelectValue('#market-filter-kind', o.kind) && o.kind !== 'all' ? o.kind : out.asset.kind,
      min: typeof o.min === 'string' ? o.min : '',
      max: typeof o.max === 'string' ? o.max : '',
      sort: _validSelectValue('#market-sort', o.sort) ? o.sort : out.asset.sort,
    };
    return out;
  }
  for (const scope of ['browse', 'asset']) {
    const src = o[scope];
    if (!src || typeof src !== 'object') continue;
    out[scope] = {
      ...out[scope],
      kind: _validSelectValue('#market-filter-kind', src.kind) ? src.kind : out[scope].kind,
      min: typeof src.min === 'string' ? src.min : '',
      max: typeof src.max === 'string' ? src.max : '',
      sort: _validSelectValue('#market-sort', src.sort) ? src.sort : out[scope].sort,
    };
  }
  if ((Number(o.version) || 0) < 4 && out.asset.kind === 'all') {
    out.asset.kind = _marketDefaultPrefs('asset').kind;
  }
  return out;
}
function _loadMarketPrefs() {
  try {
    const raw = localStorage.getItem(_PREFS_MARKET_KEY(NET.name));
    if (!raw) return _normaliseMarketPrefs(null);
    return _normaliseMarketPrefs(JSON.parse(raw));
  } catch { return _normaliseMarketPrefs(null); }
}
function _marketPrefsForScope(scope) {
  const prefs = _loadMarketPrefs();
  return prefs[scope] || _marketDefaultPrefs(scope);
}
function _applyMarketPrefsToControls(scope = marketViewScope()) {
  const prefs = _marketPrefsForScope(scope);
  const k = $('#market-filter-kind');
  const mn = $('#market-filter-min-price');
  const mx = $('#market-filter-max-price');
  const s = $('#market-sort');
  if (k && _validSelectValue('#market-filter-kind', prefs.kind)) k.value = prefs.kind;
  if (mn) mn.value = prefs.min || '';
  if (mx) mx.value = prefs.max || '';
  if (s && _validSelectValue('#market-sort', prefs.sort)) s.value = prefs.sort;
}
function _saveMarketPrefs(scope = marketViewScope()) {
  try {
    const prefs = _loadMarketPrefs();
    prefs[scope] = {
      kind: $('#market-filter-kind')?.value || _marketDefaultPrefs(scope).kind,
      min:  $('#market-filter-min-price')?.value || '',
      max:  $('#market-filter-max-price')?.value || '',
      sort: scope === 'asset' ? 'unit-asc' : ($('#market-sort')?.value || _marketDefaultPrefs(scope).sort),
    };
    prefs.version = 4;
    localStorage.setItem(_PREFS_MARKET_KEY(NET.name), JSON.stringify(prefs));
  } catch {}
}

function _setDiscoverNavCount(kind, count) {
  const el = document.getElementById(`discover-nav-${kind}-count`);
  if (!el) return;
  el.textContent = Number.isInteger(count) ? `${count} asset${count === 1 ? '' : 's'}` : '—';
}

function _setDiscoverMode(mode) {
  const panel = $('#tab-discover');
  if (!panel) return;
  const next = mode === 'mints' ? 'mints' : 'assets';
  panel.dataset.discoverMode = next;
  panel.querySelectorAll('[data-discover-nav]').forEach(a => {
    const active = (next === 'mints' && a.dataset.discoverNav === 'petch')
      || (next === 'assets' && a.dataset.discoverNav === 'cetch');
    a.classList.toggle('active', active);
    a.setAttribute('aria-selected', active ? 'true' : 'false');
  });
}

function setupDiscoverButtons() {
  const refreshBtn = $('#btn-discover-refresh');
  if (!REGISTRY_URL) { refreshBtn.disabled = true; refreshBtn.title = 'discovery disabled (no Worker)'; }
  refreshBtn.onclick = () => renderDiscover(true);
  const refreshAllBtn = $('#btn-discover-refresh-all');
  if (refreshAllBtn && !refreshAllBtn._wired) {
    refreshAllBtn._wired = true;
    if (!REGISTRY_URL && !PETCH_REGISTRY_URL) {
      refreshAllBtn.disabled = true;
      refreshAllBtn.title = 'discovery disabled (no Worker)';
    }
    refreshAllBtn.onclick = () => {
      invalidatePetchCache();
      renderDiscover(true);
    };
  }
  const allLink = $('#recent-etches-all');
  if (allLink) allLink.onclick = (e) => { e.preventDefault(); $('.tab[data-tab="discover"]').click(); };
  _setDiscoverMode('assets');
  document.querySelectorAll('a[data-discover-nav]').forEach(a => {
    a.addEventListener('click', (e) => {
      e.preventDefault();
      _setDiscoverMode(a.dataset.discoverNav === 'petch' ? 'mints' : 'assets');
    });
  });
  const panel = $('#tab-discover');
  if (panel) {
    panel.addEventListener('click', (e) => {
      const a = e.target.closest('a[data-goto-tab]');
      if (!a) return;
      e.preventDefault();
      const t = document.querySelector(`.tab[data-tab="${a.dataset.gotoTab}"]`);
      if (t) t.click();
    });
  }
  const filterInput = $('#discover-filter');
  const petchFilterInput = $('#petch-filter');
  if (filterInput) {
    let t = null;
    filterInput.addEventListener('input', () => {
      if (petchFilterInput && petchFilterInput.value !== filterInput.value) {
        petchFilterInput.value = filterInput.value;
      }
      clearTimeout(t);
      t = setTimeout(applyDiscoverFilter, 200);
    });
  }
  if (petchFilterInput && filterInput) {
    let pt = null;
    petchFilterInput.addEventListener('input', () => {
      filterInput.value = petchFilterInput.value;
      clearTimeout(pt);
      pt = setTimeout(applyDiscoverFilter, 200);
    });
  }
  const petchRefreshBtn = $('#btn-petch-discover-refresh');
  if (petchRefreshBtn) {
    if (!REGISTRY_URL) { petchRefreshBtn.disabled = true; petchRefreshBtn.title = 'discovery disabled (no Worker)'; }
    petchRefreshBtn.onclick = () => {
      invalidatePetchCache();
      renderPetchDiscover().catch(() => {});
    };
  }
  const pills = $('#discover-pills');
  if (pills) {
    pills.addEventListener('click', e => {
      const btn = e.target.closest('.filter-pill[data-pill]');
      if (!btn) return;
      _discoverPill = btn.dataset.pill;
      pills.querySelectorAll('.filter-pill').forEach(b => {
        b.classList.toggle('active', b.dataset.pill === _discoverPill);
      });
      _saveDiscoverPrefs();
      applyDiscoverFilter();
    });
  }
  const sortSel = $('#discover-sort');
  if (sortSel) {
    sortSel.addEventListener('change', () => {
      _discoverSort = sortSel.value || 'newest';
      _saveDiscoverPrefs();
      applyDiscoverSort();
    });
  }
  const petchSortSel = $('#petch-sort');
  if (petchSortSel) {
    petchSortSel.addEventListener('change', () => {
      _petchSort = petchSortSel.value || 'newest';
      _saveDiscoverPrefs();
      renderPetchDiscover().catch(() => {});
    });
  }
  const petchPills = $('#petch-pills');
  if (petchPills) {
    petchPills.addEventListener('click', e => {
      const btn = e.target.closest('.filter-pill[data-petch-pill]');
      if (!btn) return;
      _petchPill = btn.dataset.petchPill;
      petchPills.querySelectorAll('.filter-pill').forEach(b => {
        b.classList.toggle('active', b.dataset.petchPill === _petchPill);
      });
      _saveDiscoverPrefs();
      applyDiscoverFilter();
    });
  }
  const _prefs = _loadDiscoverPrefs();
  if (_prefs) {
    if (sortSel && typeof _prefs.sort === 'string') {
      const valid = Array.from(sortSel.options).some(o => o.value === _prefs.sort);
      if (valid) { sortSel.value = _prefs.sort; _discoverSort = _prefs.sort; }
    }
    if (pills && typeof _prefs.pill === 'string') {
      const target = pills.querySelector(`.filter-pill[data-pill="${CSS.escape(_prefs.pill)}"]`);
      if (target) {
        _discoverPill = _prefs.pill;
        pills.querySelectorAll('.filter-pill').forEach(b => {
          b.classList.toggle('active', b.dataset.pill === _discoverPill);
        });
      }
    }
    if (petchSortSel && typeof _prefs.petchSort === 'string') {
      const valid = Array.from(petchSortSel.options).some(o => o.value === _prefs.petchSort);
      if (valid) { petchSortSel.value = _prefs.petchSort; _petchSort = _prefs.petchSort; }
    }
    if (petchPills && typeof _prefs.petchPill === 'string') {
      const target = petchPills.querySelector(`.filter-pill[data-petch-pill="${CSS.escape(_prefs.petchPill)}"]`);
      if (target) {
        _petchPill = _prefs.petchPill;
        petchPills.querySelectorAll('.filter-pill').forEach(b => {
          b.classList.toggle('active', b.dataset.petchPill === _petchPill);
        });
      }
    }
  }
}

function setupMarketButtons() {
  const refreshBtn = $('#btn-market-refresh');
  if (refreshBtn) {
    if (!REGISTRY_URL) { refreshBtn.disabled = true; refreshBtn.title = 'market disabled (no Worker)'; }
    refreshBtn.onclick = () => { invalidateMarketCache(); renderMarket(); };
  }
  const txt = $('#market-filter-asset');
  if (txt) {
    let t = null;
    txt.addEventListener('input', () => {
      clearTimeout(t);
      t = setTimeout(() => { _marketBrowsePage = 1; _marketListingPage = 1; applyMarketFilters(); }, 80);
    });
  }
  ['#market-filter-kind', '#market-filter-min-price', '#market-filter-max-price', '#market-sort'].forEach(sel => {
    const el = $(sel);
    if (el) el.addEventListener('change', () => { _marketBrowsePage = 1; _marketListingPage = 1; _saveMarketPrefs(); applyMarketFilters(); });
  });
  const priceChip = $('#market-price-chip');
  const pricePop = $('#market-price-popover');
  const priceClear = $('#market-price-clear');
  const priceDone = $('#market-price-done');
  if (priceChip && pricePop) {
    const closePop = () => {
      pricePop.hidden = true;
      priceChip.setAttribute('aria-expanded', 'false');
      document.removeEventListener('click', _onDocClickPricePop, true);
      document.removeEventListener('keydown', _onKeyPricePop, true);
    };
    const _onDocClickPricePop = (e) => {
      if (pricePop.hidden) return;
      if (pricePop.contains(e.target) || priceChip.contains(e.target)) return;
      closePop();
    };
    const _onKeyPricePop = (e) => { if (e.key === 'Escape') closePop(); };
    priceChip.addEventListener('click', () => {
      const open = pricePop.hidden;
      pricePop.hidden = !open;
      priceChip.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (open) {
        document.addEventListener('click', _onDocClickPricePop, true);
        document.addEventListener('keydown', _onKeyPricePop, true);
        $('#market-filter-min-price')?.focus();
      } else {
        document.removeEventListener('click', _onDocClickPricePop, true);
        document.removeEventListener('keydown', _onKeyPricePop, true);
      }
    });
    if (priceDone) priceDone.addEventListener('click', closePop);
    if (priceClear) priceClear.addEventListener('click', () => {
      const mn = $('#market-filter-min-price');
      const mx = $('#market-filter-max-price');
      if (mn) mn.value = '';
      if (mx) mx.value = '';
      _marketBrowsePage = 1;
      _marketListingPage = 1;
      _saveMarketPrefs();
      applyMarketFilters();
    });
  }
  _applyMarketPrefsToControls('browse');
}

async function autoImportShareLink() {
  if (!location.hash.includes('recv=')) return;
  const hash = location.hash.slice(location.hash.indexOf('#recv='));
  const claim = decodeShareLinkHash(hash);
  if (!claim) {
    toast('Share-link in URL is malformed; ignoring.', 'error');
    history.replaceState(null, '', location.pathname + location.search);
    return;
  }
  const human = `${fmtAssetAmount(claim.amount, claim.decimals)} ${claim.ticker || '???'}`;
  const needsUnlock = !!wallet.pub && !wallet.priv;
  const ok = await tacitConfirm({
    title: 'Import received share-link?',
    body:
      `Claim: ${human}\nAsset: ${claim.assetIdHex.slice(0, 16)}…\nUTXO: ${claim.txid.slice(0, 16)}…:${claim.vout}\n\n` +
      `Importing will validate the claim against on-chain data and (if valid) record an opening in your local wallet. Cancel if you didn't expect this link.` +
      (needsUnlock
        ? `\n\nAfter you confirm, you'll be prompted to unlock your wallet — the import needs your key to derive the recipient blinding.`
        : ''),
    confirmLabel: 'Import',
  });
  history.replaceState(null, '', location.pathname + location.search);
  if (!ok) {
    toast('Share-link import declined.', '');
    return;
  }
  try {
    const data = await importShareLink(hash);
    toast(`Imported ${fmtAssetAmount(data.amount, data.decimals)} ${data.ticker} from URL`, 'success');
    markOnboarded();
    $('.tab[data-tab="holdings"]').click();
  } catch (e) {
    if (isUnlockCancelled(e)) {
      toast('Unlock cancelled — share-link not imported. Re-open the link to retry.', '');
    } else {
      toast('Auto-import failed: ' + e.message, 'error');
      console.error('auto-import failed:', e);
    }
  }
}

function setupNetworkSelect() {
  const sel = $('#net-select');
  if (!sel) return;
  sel.value = NET.name;
  const btcLogo = $('#net-btc-logo');
  if (btcLogo) btcLogo.classList.toggle('net-btc-logo-signet', NET.name === 'signet');
  const dh = $('#discover-header-title');
  if (dh) dh.textContent = `assets · ${NET.name}`;
  const banner = $('#mainnet-banner');
  const mainnetAcked = localStorage.getItem(MAINNET_OK_KEY) === '1';
  if (banner) {
    banner.style.display = (NET.name === 'mainnet' && !mainnetAcked) ? 'block' : 'none';
  }
  const detailEl = $('#mainnet-banner-detail');
  if (detailEl && NET.name === 'mainnet' && !mainnetAcked) {
    const isPasskey = wallet.mode === 'passkey';
    const hasExt = !!wallet.ext;
    const backedUp = isBurnerBackedUp();
    let detail = '';
    if (!isPasskey && !hasExt && !backedUp) {
      detail = 'Burner key isn\'t backed up — export it or connect Xverse / Leather / UniSat before sending.';
    } else if (!isPasskey && !hasExt && backedUp) {
      detail = 'Using an in-browser burner key — connect Xverse / Leather / UniSat for meaningful balances.';
    } else if (!isPasskey && !backedUp) {
      detail = 'Tacit signing key isn\'t backed up — export it from the wallet tab before sending.';
    }
    detailEl.textContent = detail;
  }
  const closeBtn = $('#mainnet-banner-close');
  if (closeBtn && !closeBtn._wired) {
    closeBtn._wired = true;
    closeBtn.onclick = () => {
      localStorage.setItem(MAINNET_OK_KEY, '1');
      const b = $('#mainnet-banner'); if (b) b.style.display = 'none';
    };
  }
  const lockHint = $('#net-lock-hint');
  if (wallet.ext) {
    sel.disabled = true;
    sel.title = 'Connected wallet drives the network — switch in your wallet, or disconnect first.';
    if (lockHint) lockHint.style.display = '';
    const provider = wallet.ext.provider === 'sats-connect' ? 'Xverse / Leather' : (wallet.ext.provider || 'wallet');
    const lbl = lockHint?.querySelector('a');
    if (lbl) lbl.textContent = `disconnect ${provider}`;
  } else {
    sel.disabled = false;
    sel.title = '';
    if (lockHint) lockHint.style.display = 'none';
  }
  const disconnectLink = $('#net-lock-disconnect');
  if (disconnectLink) {
    disconnectLink.onclick = (e) => {
      e.preventDefault();
      if (!wallet.ext) return;
      if (typeof applyExtDisconnect === 'function') applyExtDisconnect();
    };
  }
  sel.onchange = async () => {
    const next = sel.value === 'mainnet' ? 'mainnet' : 'signet';
    if (next === NET.name) return;
    if (next === 'mainnet' && !localStorage.getItem(MAINNET_OK_KEY)) {
      const ok = await tacitConfirm({
        title: '⚠ Switch to Bitcoin mainnet?',
        body:
          'This is real money. Tacit is experimental software with no warranty. ' +
          'You may lose funds to bugs, fee miscalculation, lost private keys, ' +
          'or any number of issues that haven\'t shown up on signet yet.\n\n' +
          'Recommended: test thoroughly on signet first. Only put amounts on mainnet ' +
          'that you can afford to lose.',
        confirmLabel: 'Continue to mainnet',
        kind: 'danger',
      });
      if (!ok) { sel.value = NET.name; return; }
      localStorage.setItem(MAINNET_OK_KEY, '1');
    }
    try {
      localStorage.setItem('tacit-net-flip-toast-v1', JSON.stringify({
        prev: NET.name,
        prevAddr: wallet.pub ? wallet.address() : null,
        next,
        ts: Date.now(),
      }));
    } catch {}
    localStorage.setItem(NET_KEY, next);
    location.reload();
  };
}

function consumePendingNetFlipToast() {
  let payload;
  try {
    const raw = localStorage.getItem('tacit-net-flip-toast-v1');
    if (!raw) return;
    payload = JSON.parse(raw);
  } catch { localStorage.removeItem('tacit-net-flip-toast-v1'); return; }
  localStorage.removeItem('tacit-net-flip-toast-v1');
  if (!payload || payload.next !== NET.name) return;
  const prevTag = payload.prev || 'previous network';
  const prevSnippet = payload.prevAddr ? ` (${shorten(payload.prevAddr, 8)})` : '';
  toast(
    `Switched to ${payload.next}. Your ${prevTag} wallet${prevSnippet} is preserved separately — this is a fresh ${payload.next} wallet at your current address. Both networks have independent keys; export each one before holding value.`,
    '',
    9000,
  );
}

function _hasUnboundLocalWallet() {
  const raw = localStorage.getItem(walletStorageKey());
  return typeof raw === 'string' && raw.trim().length > 0;
}

function _findCrossNetworkLocalWallet() {
  const otherNet = NET.name === 'mainnet' ? 'signet' : 'mainnet';
  const otherKey = `${WALLET_KEY_BASE}:${otherNet}`;
  try {
    const raw = localStorage.getItem(otherKey);
    if (!raw) return null;
    const pub = readBlobPub(raw);
    return { otherNet, otherKey, raw, pub };
  } catch { return null; }
}

async function _importCrossNetworkWallet({ otherNet, raw }) {
  const srcPassphrase = await _promptUnlockPassphrase(`Unlock your ${otherNet} wallet to use it on ${NET.name} too.`);
  const priv = await decryptPrivkey(raw, srcPassphrase);
  const prevPub = _openPubHex();
  wallet.priv = priv;
  wallet.pub = secp.getPublicKey(priv, true);
  _onIdentityChanged(prevPub);
  const newKey = walletStorageKey();
  localStorage.setItem(newKey, await encryptPrivkey(priv, srcPassphrase));
  setActiveWalletMode('local');
}

function setupFaqModal() {
  const btn = document.getElementById('btn-faq');
  const modal = document.getElementById('faq-modal');
  const closeBtn = document.getElementById('faq-close');
  if (!btn || !modal || !closeBtn) return;
  const open = () => { modal.style.display = 'grid'; closeBtn.focus(); };
  const close = () => { modal.style.display = 'none'; };
  btn.addEventListener('click', open);
  closeBtn.addEventListener('click', close);
  modal.addEventListener('click', (e) => { if (e.target === modal) close(); });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && modal.style.display !== 'none') close();
  });
}

function setupProtocolToc() {
  const toc = document.querySelector('.protocol-toc');
  if (!toc) return;
  toc.addEventListener('click', (e) => {
    const a = e.target.closest('a[href^="#proto-"]');
    if (!a) return;
    const target = document.getElementById(a.getAttribute('href').slice(1));
    if (target && target.tagName === 'DETAILS') target.open = true;
  });
}

let _welcomeModalInflight = null;
function _showWelcomeModal() {
  if (_welcomeModalInflight) return _welcomeModalInflight;
  _welcomeModalInflight = new Promise((resolve) => {
    const settle = (v) => { _welcomeModalInflight = null; resolve(v); };
    const modal = document.getElementById('welcome-modal');
    const xBtn = document.getElementById('welcome-xverse');
    const uBtn = document.getElementById('welcome-unisat');
    const eBtn = document.getElementById('welcome-eth');
    const pBtn = document.getElementById('welcome-passkey');
    const lBtn = document.getElementById('welcome-local');
    const cBtn = document.getElementById('welcome-crossnet');
    const bidBtn = document.getElementById('welcome-btc-id');
    const browseBtn = document.getElementById('welcome-browse');
    if (!modal || !xBtn || !uBtn || !pBtn || !lBtn) { settle('local'); return; }
    const crossNet = (typeof _findCrossNetworkLocalWallet === 'function')
      ? _findCrossNetworkLocalWallet()
      : null;
    if (cBtn) {
      if (crossNet && crossNet.pub) {
        const addrStr = (() => {
          try { return p2wpkhAddress(crossNet.pub); } catch { return ''; }
        })();
        const title = document.getElementById('welcome-crossnet-title');
        const meta  = document.getElementById('welcome-crossnet-meta');
        if (title) title.innerHTML = `use your ${escapeHtml(crossNet.otherNet)} wallet here too <span class="welcome-option-rec">(recommended)</span>`;
        if (meta)  meta.textContent  = addrStr
          ? `Unlock ${shorten(addrStr, 10)} (${crossNet.otherNet}) and use the same signing key on ${NET.name} too. One passphrase, one identity across both networks — matches the way passkey already works.`
          : `Unlock your ${crossNet.otherNet} wallet and use the same signing key on ${NET.name}. One passphrase, one identity across both networks.`;
        cBtn.style.display = '';
        pBtn.classList.remove('welcome-option--primary');
        lBtn.classList.remove('welcome-option--primary');
      } else {
        cBtn.style.display = 'none';
      }
    }
    try {
      const ctx = document.getElementById('welcome-ceremony-context');
      const _qs = new URLSearchParams(window.location.search);
      const _hash = (window.location.hash || '').replace(/^#/, '');
      const _hashQs = new URLSearchParams(_hash.includes('=') ? _hash : '');
      const fromUrl = _qs.get('ceremony');
      const wantsMixer = fromUrl && fromUrl.toLowerCase() === TACIT_DEFAULT_CEREMONY_HASH;
      const wantsAmm =
        _qs.get('amm') === 'ceremony'
        || _qs.has('ammceremony')
        || _hashQs.get('amm') === 'ceremony'
        || _hash === 'ammceremony'
        || _hash === 'amm-ceremony';
      if (ctx && (wantsMixer || wantsAmm)) {
        if (wantsAmm) {
          ctx.innerHTML = 'You followed a share link to the <strong>tacit AMM trusted setup ceremony</strong>. Pick a wallet setup below — passkey is the one-tap path; your contribution gets logged against your wallet for airdrop eligibility. The contribute drawer opens right after.';
        }
        ctx.style.display = 'block';
      }
    } catch {}
    const av = extWallet.available();
    xBtn.disabled = !av.satsConnect;
    xBtn.title = av.satsConnect ? '' : 'Xverse / Leather extension not detected';
    uBtn.disabled = !av.unisat;
    uBtn.title = av.unisat ? '' : 'UniSat extension not detected';
    if (bidBtn) {
      const anyBtc = av.satsConnect || av.unisat;
      bidBtn.disabled = !anyBtc;
      bidBtn.title = anyBtc ? '' : 'No Bitcoin wallet extension detected';
    }
    if (eBtn) {
      eBtn.disabled = !ethWallet.available();
      eBtn.title = ethWallet.available() ? '' : 'No Ethereum wallet detected';
    }
    pBtn.disabled = !prfWallet.available();
    pBtn.title = prfWallet.available() ? '' : 'Passkey requires HTTPS (or localhost)';
    const passkeyRec = document.getElementById('welcome-passkey-rec');
    const localRec = document.getElementById('welcome-local-rec');
    if (prfWallet.available()) {
      pBtn.classList.add('welcome-option--primary');
      lBtn.classList.remove('welcome-option--primary');
      if (passkeyRec) passkeyRec.style.display = '';
      if (localRec) localRec.style.display = 'none';
    } else {
      pBtn.classList.remove('welcome-option--primary');
      lBtn.classList.add('welcome-option--primary');
      if (passkeyRec) passkeyRec.style.display = 'none';
      if (localRec) localRec.style.display = '';
    }
    const iLink = document.getElementById('welcome-import');
    const close = (choice) => {
      xBtn.onclick = uBtn.onclick = pBtn.onclick = lBtn.onclick = null;
      if (eBtn) eBtn.onclick = null;
      if (cBtn) cBtn.onclick = null;
      if (bidBtn) bidBtn.onclick = null;
      if (browseBtn) browseBtn.onclick = null;
      if (iLink) iLink.onclick = null;
      modal.style.display = 'none';
      settle(choice);
    };
    xBtn.onclick = () => close('ext-xverse');
    uBtn.onclick = () => close('ext-unisat');
    if (bidBtn) bidBtn.onclick = () => close('btc-id');
    if (eBtn) eBtn.onclick = () => close('eth');
    pBtn.onclick = () => close('passkey');
    lBtn.onclick = () => close('local');
    if (cBtn) cBtn.onclick = () => close('crossnet');
    if (browseBtn) browseBtn.onclick = () => close('browse');
    if (iLink) iLink.onclick = (e) => { e.preventDefault(); close('import'); };
    const cerDrawer = document.getElementById('evm-cer-drawer');
    if (cerDrawer && cerDrawer.style.display !== 'none') globalThis.__tacitWelcomeDeferred = () => { modal.style.display = 'flex'; };
    else modal.style.display = 'flex';
  });
  return _welcomeModalInflight;
}

async function _promptImportKey({ reason } = {}) {
  const modal = document.getElementById('import-modal');
  const txt = document.getElementById('import-key-text');
  const reasonEl = document.getElementById('import-reason');
  const errEl = document.getElementById('import-error');
  const okBtn = document.getElementById('import-confirm');
  const cancelBtn = document.getElementById('import-cancel');
  if (!modal || !txt || !okBtn || !cancelBtn) {
    const v = prompt('Paste tacit private key (64 hex chars):');
    if (!v) throw _newUnlockCancelledError();
    return v.trim();
  }
  txt.value = '';
  if (errEl) errEl.textContent = '';
  if (reasonEl && reason) reasonEl.textContent = reason;
  modal.style.display = '';
  setTimeout(() => { try { txt.focus(); } catch {} }, 50);
  return new Promise((resolve, reject) => {
    const cleanup = () => {
      okBtn.onclick = null;
      cancelBtn.onclick = null;
      modal.style.display = 'none';
      if (errEl) errEl.textContent = '';
      txt.value = '';
    };
    okBtn.onclick = () => {
      const v = (txt.value || '').trim();
      if (!v) { if (errEl) errEl.textContent = 'paste a private key first'; return; }
      if (!/^[0-9a-f]{64}$/i.test(v)) { if (errEl) errEl.textContent = 'must be 64 hex chars'; return; }
      cleanup();
      resolve(v);
    };
    cancelBtn.onclick = () => { cleanup(); reject(_newUnlockCancelledError()); };
  });
}

async function _runFirstLoadChoice() {
  while (true) {
    const choice = await _showWelcomeModal();
    try {
      if (choice === 'browse') {
        if (typeof markOnboarded === 'function') markOnboarded();
        return 'browse';
      } else if (choice === 'ext-xverse' || choice === 'ext-unisat') {
        const st = choice === 'ext-xverse'
          ? await extWallet.connectSatsConnect()
          : await extWallet.connectUnisat();
        const verdict = reconcileWalletNetwork(st);
        if (verdict === 'reload') return 'reload';
        if (verdict === 'unsupported') continue;
        await wallet.load(st.address);
        setActiveWalletMode('ext');
      } else if (choice === 'btc-id') {
        const st = await extWallet.connectDefault();
        const verdict = reconcileWalletNetwork(st);
        if (verdict === 'reload') return 'reload';
        if (verdict === 'unsupported') continue;
        try {
          await btcWallet.enroll();
          if (typeof markOnboarded === 'function') markOnboarded();
        } catch (e) {
          if (!e?._btcNonDeterministic) throw e;
          toast('This wallet signs non-deterministically — connecting it as a funding wallet with a local tacit key instead. Back the key up from Manage Wallet.', 'warn', 9000);
          await wallet.load(st.address);
          setActiveWalletMode('ext');
          if (typeof markOnboarded === 'function') markOnboarded();
        }
      } else if (choice === 'eth') {
        await ethWallet.login();
        if (typeof markOnboarded === 'function') markOnboarded();
      } else if (choice === 'passkey') {
        if (!await _showPasskeyModal()) throw new Error('cancelled');
      } else if (choice === 'import') {
        const hex = await _promptImportKey({
          reason: 'paste a 64-char hex tacit private key to restore your wallet. you\'ll set a fresh passphrase next to encrypt it at rest in this browser.',
        });
        await wallet.setPriv(hex);
        setActiveWalletMode('local');
        try {
          const addrStr = wallet.pub ? wallet.address() : '';
          toast(`Restored ${shorten(addrStr || '', 10)} from key.`, 'success', 6000);
        } catch {}
      } else if (choice === 'crossnet') {
        const xnet = _findCrossNetworkLocalWallet();
        if (!xnet) {
          continue;
        }
        await _importCrossNetworkWallet(xnet);
        try {
          const addrStr = wallet.pub ? wallet.address() : '';
          toast(
            `Using your ${xnet.otherNet} wallet (${shorten(addrStr || '', 10)}) on ${NET.name} too. Same signing key on both networks.`,
            'success', 7000,
          );
        } catch {}
      } else {
        await wallet.load();
        setActiveWalletMode('local');
      }
      return;
    } catch (e) {
      extWallet.disconnect();
      wallet.ext = null;
      ethWallet.disconnect();
      if (!e || e.message === 'cancelled') continue;
      toast('Setup failed: ' + (e?.message || e), 'error', 5000);
    }
  }
}

async function init() {
  try { runStartupKAT(); }
  catch (e) {
    document.body.innerHTML =
      '<div style="max-width:680px;margin:80px auto;padding:24px;border:2px solid #b8341d;background:#fee;font-family:ui-monospace,monospace;color:#0a0a0a;">' +
      '<h2 style="color:#b8341d;font-family:serif;font-style:italic;margin-bottom:12px;">tacit refuses to start</h2>' +
      '<p style="margin-bottom:8px;">A startup integrity check failed. The cryptographic libraries this dApp depends on returned an unexpected answer for a known input — the bundle has likely been tampered with, drifted, or failed to load correctly. Using this page to manage tokens would be unsafe.</p>' +
      '<pre style="background:#fff;border:1px solid #0a0a0a;padding:10px;font-size:11px;white-space:pre-wrap;word-break:break-all;">' + escapeHtml(e.message) + '</pre>' +
      '<p style="margin-top:12px;font-size:12px;">Reload the page; if the failure persists, do not enter any private keys here. File an issue with the message above.</p>' +
      '</div>';
    throw e;
  }
  if (location.protocol === 'file:') {
    const w = document.getElementById('file-protocol-warning');
    if (w) w.style.display = 'block';
  }
  try { renderEvmPoolCeremony(); } catch {}
  if (!globalThis.__tacitEvmCerTimer) globalThis.__tacitEvmCerTimer = setInterval(() => { try { renderEvmPoolCeremony(); } catch {} }, 60_000);
  if (location.hash && location.hash.startsWith('#tab=market') && typeof fetchMarketDataDeduped === 'function' && typeof MARKET_URL === 'string' && MARKET_URL) {
    try {
      fetchMarketDataDeduped().catch(e => console.warn('[market] deep-link pre-fetch failed:', e?.message || e));
    } catch {}
  }
  const activeMode = getActiveWalletMode();
  if (activeMode === 'eth') {
    const ethRestored = ethWallet.tryRestore();
    if (ethRestored?.pubkey) {
      try {
        wallet.pub = hexToBytes(ethRestored.pubkey);
        wallet.mode = 'eth';
      } catch (e) {
        console.warn('eth wallet pubkey hydration failed:', e.message);
        ethWallet.disconnect();
      }
    } else if (ethRestored?.address) {
      wallet.mode = 'eth';
    }
  }
  if (activeMode === 'btc') {
    const btcRestored = btcWallet.tryRestore();
    if (btcRestored?.tacitPubkey) {
      try { await extWallet.tryRestore(); } catch {}
      try {
        wallet.pub = hexToBytes(btcRestored.tacitPubkey);
        wallet.mode = 'btc';
      } catch (e) {
        console.warn('btc wallet pubkey hydration failed:', e.message);
        btcWallet.disconnect();
      }
    } else if (btcRestored?.address) {
      try { await extWallet.tryRestore(); } catch {}
      wallet.mode = 'btc';
    }
  }
  const restoredPasskey = prfWallet.tryRestore();
  let bootstrapped = false;
  if (activeMode === 'eth' && wallet.mode === 'eth') {
    bootstrapped = true;
  } else if (activeMode === 'btc' && wallet.mode === 'btc') {
    bootstrapped = true;
  } else if (restoredPasskey && activeMode !== 'ext' && activeMode !== 'local') {
    if (restoredPasskey.pubkey) {
      try {
        wallet.pub = hexToBytes(restoredPasskey.pubkey);
        wallet.mode = 'passkey';
        bootstrapped = true;
      } catch (e) {
        console.warn('passkey pubkey hydration failed:', e.message);
        prfWallet.state = null;
      }
    } else {
      try {
        await prfWallet.login({ label: restoredPasskey.label });
        bootstrapped = true;
      } catch (e) {
        prfWallet.lock();
        console.warn('passkey legacy auto-login failed:', e.message);
      }
    }
  }
  if (!bootstrapped) {
    const restored = await extWallet.tryRestore().catch(() => null);
    let extOk = false;
    if (restored) {
      const verdict = reconcileWalletNetwork(restored);
      if (verdict === 'reload') return;
      extOk = verdict === 'ok';
    }
    if (extOk) {
      const key = walletStorageKey(restored.address);
      const raw = localStorage.getItem(key);
      const pub = raw ? readBlobPub(raw) : null;
      if (pub) {
        wallet.pub = pub;
        setActiveWalletMode('ext');
      } else if (_storageShape(raw) === 'encrypted') {
        try {
          await wallet.load(restored.address);
          setActiveWalletMode('ext');
        } catch (e) {
          if (e?.message !== 'cancelled') {
            toast(`Couldn't unlock burner: ${e?.message || e}.`, 'error', 6000);
          }
          if (await _runFirstLoadChoice() === 'reload') return;
        }
      } else {
        if (await _runFirstLoadChoice() === 'reload') return;
      }
    } else if (_hasUnboundLocalWallet()) {
      const raw = localStorage.getItem(walletStorageKey());
      const pub = readBlobPub(raw);
      if (pub) {
        wallet.pub = pub;
        setActiveWalletMode('local');
      } else if (_storageShape(raw) === 'encrypted') {
        try {
          await wallet.load();
          setActiveWalletMode('local');
        } catch (e) {
          if (e?.message !== 'cancelled') {
            toast(`Couldn't unlock local wallet: ${e?.message || e}. Pick another option below.`, 'error', 6000);
          }
          if (await _runFirstLoadChoice() === 'reload') return;
        }
      } else {
        if (await _runFirstLoadChoice() === 'reload') return;
      }
    } else {
      if (typeof isOnboarded === 'function' && isOnboarded()) {
      } else {
        if (await _runFirstLoadChoice() === 'reload') return;
      }
    }
  }
  setupNetworkSelect();
  setupTabs();
  setupMixerHandlers();
  setupCeremonyHandlers();
  try {
    fetchMarketDataDeduped()
      .then(() => { try { _renderGlobalTape(); } catch {} })
      .catch(() => {});
  } catch {}
  try { _renderAmmContribTape(); } catch {}
  try {
    if (typeof window !== 'undefined') {
      const _qs = new URLSearchParams(window.location.search || '');
      const _hash = (window.location.hash || '').replace(/^#/, '');
      const _hashQs = new URLSearchParams(_hash.includes('=') ? _hash : '');
      const wantsAmmCeremony =
        _qs.get('amm') === 'ceremony'
        || _qs.has('ammceremony')
        || _hashQs.get('amm') === 'ceremony'
        || _hash === 'ammceremony'
        || _hash === 'amm-ceremony';
      if (wantsAmmCeremony) {
        setTimeout(async () => {
          try {
            const haveWallet = !!(wallet && wallet.pub);
            if (!haveWallet && typeof _showWelcomeModal === 'function') {
              try { await _showWelcomeModal(); } catch { }
            }
            openAmmCeremonyDrawer();
          } catch (e) { console.warn('[amm-deeplink] open failed', e?.message); }
        }, 250);
      }
    }
  } catch {}
  try { _wireAmmCeremonyChipOnce(); renderAmmCeremonyChip(); } catch {}
  try { renderEvmPoolCeremony(); } catch {}
  setupFaqModal();
  setupProtocolToc();
  setupWalletButtons();
  const _deferIdle = (fn, ms = 1500) => (typeof requestIdleCallback === 'function'
    ? requestIdleCallback(() => { try { fn(); } catch {} }, { timeout: ms + 1000 })
    : setTimeout(() => { try { fn(); } catch {} }, ms));
  _deferIdle(() => { _runCandidateProbe().catch(() => {}); });
  setupExtWalletButtons();
  setupEthWalletButtons();
  try { mountAirdropAnnouncement({ eth: ethNamesBridge }); } catch (e) { console.error('airdrop banner', e); }
  setupBtcWalletButtons();
  setupPasskeyButtons();
  setupUnisatEvents();
  setupEtchForm();
  setupPetchForm();
  setupTransferForm();
  setupSatsSendForm();
  setupDropsForm();
  try { _autoFulfilResumeAll(); } catch (e) { console.warn('auto-fulfil resume failed:', e); }
  setupClaimTab();
  setupHoldingsButtons();
  setupDiscoverButtons();
  setupMarketButtons();
  _deferIdle(startChainDivergenceWatchdog);
  renderBppSignetBanner();
  renderSatsFragmentationBanner();
  renderRecentEtches();
  if ((location.hash || '').startsWith('#tab=')) {
    try { _consumeTabUrlHash(); } catch (e) { console.warn('[init] early tab deeplink failed:', e?.message || e); }
  }
  await refreshWallet();
  renderExtWalletPanel();
  renderEthWalletPanel();
  renderBtcWalletPanel();
  consumePendingNetFlipToast();
  _recoverPendingReveal().catch(() => {});
  await autoImportShareLink();
  _consumeClaimUrlHash();
  _consumeGateUrlHash();
  _consumeTabUrlHash();
  if (/^#tab=govern\b/.test(location.hash || '')) {
    try { renderGovernTab(wallet, governanceApi()); } catch (e) { console.error('govern tab', e); }
  }
  if (/^#tab=points\b/.test(location.hash || '')) {
    try { renderPointsTab(wallet, { eth: evmTradeLaneWallet }); } catch (e) { console.error('points tab', e); }
  }
  if (_loadAutoFulfilFlag()) {
    try { startAutoFulfilDaemon(); } catch (e) { console.warn('auto-fulfil bootstrap failed:', e); }
  }
  const _axintentResumeTick = (attempt) => resumePendingAxintents().then((r) => {
    const remaining = listAxintentPendings();
    if (!remaining.length) {
      if (attempt > 0 && r.attempted > 0) {
        toast(`Pending atomic intent${r.attempted === 1 ? '' : 's'} published ✓ — now live on the Market tab.`, 'success', 9000);
        try { invalidateMarketCache(); } catch {}
      }
      return;
    }
    if (attempt < 4) setTimeout(() => _axintentResumeTick(attempt + 1), 120_000 * Math.pow(2, attempt));
    if (attempt === 0) {
      const why = r.failures[0]?.reason || '';
      const whyShort = /failed to fetch|networkerror|load failed|unreachable|all chain apis/i.test(why)
        ? 'chain API / marketplace unreachable'
        : why.slice(0, 120);
      toast(
        `${remaining.length} atomic intent${remaining.length === 1 ? '' : 's'} couldn't be published yet ` +
        `(commit tx broadcast, marketplace POST pending${whyShort ? ` — ${whyShort}` : ''}). ` +
        `Retrying automatically in the background — your Bitcoin fees are not lost.`,
        '', 12000,
      );
    }
  }).catch(e => console.warn('[axintent] resume failed:', e));
  _axintentResumeTick(0);
  try { _ensureAxferClaimsPoller(); } catch {}
  try { _ensureAxferClaimsTtlTicker(); } catch {}
  const preauthPendings = listPreauthTakePendings();
  if (preauthPendings.length) {
    const seen = loadPreauthTakePendingSeen();
    const unseen = preauthPendings.filter(p => !seen.has(p.commitTxidHex));
    if (unseen.length > 0) {
      const totalSats = preauthPendings.reduce((s, p) => s + (Number(p.commit_value) || 0), 0);
      const newLabel = (unseen.length < preauthPendings.length)
        ? ` (${unseen.length} new)`
        : '';
      toast(
        `⚠ ${preauthPendings.length} stranded preauth-take commit${preauthPendings.length === 1 ? '' : 's'}${newLabel} ` +
        `(~${totalSats.toLocaleString()} sats recoverable). Open Holdings → Recover.`,
        'warn', 15000,
      );
      for (const p of preauthPendings) seen.add(p.commitTxidHex);
      savePreauthTakePendingSeen(seen);
    }
  }
  if (wallet.pub) startMakerClaimPoller();
  scheduleBidWalletReturn();
  startCountdownTicker();
}
if (!globalThis.__TACIT_NO_INIT__) {
  init().catch(e => { toast('Init error: ' + e.message, 'error'); console.error(e); });
}

function isOnboarded() {
  return localStorage.getItem(ONBOARDED_KEY) === '1';
}
function markOnboarded() {
  if (isOnboarded()) return;
  localStorage.setItem(ONBOARDED_KEY, '1');
}


function openInlineForm(triggerBtn, { content, submitLabel = 'Confirm', submitClass = 'primary', cancelLabel = 'Cancel', onSubmit, onClose }) {
  const existing = triggerBtn.nextElementSibling;
  if (existing && existing.classList.contains('inline-form-host')) {
    existing.remove();
    if (onClose) onClose();
    return null;
  }
  const host = document.createElement('div');
  host.className = 'inline-form-host';
  host.innerHTML = `
    <div class="inline-form">
      ${content}
      <div class="form-buttons">
        <button class="${submitClass}" data-form-act="submit">${escapeHtml(submitLabel)}</button>
        <button data-form-act="cancel">${escapeHtml(cancelLabel)}</button>
      </div>
      <div class="error" data-form-error></div>
    </div>`;
  triggerBtn.insertAdjacentElement('afterend', host);
  const errEl = host.querySelector('[data-form-error]');
  const submitBtn = host.querySelector('[data-form-act="submit"]');
  const cancelBtn = host.querySelector('[data-form-act="cancel"]');
  const close = () => { host.remove(); if (onClose) onClose(); };
  cancelBtn.onclick = close;
  submitBtn.onclick = async () => {
    errEl.textContent = '';
    submitBtn.disabled = true; cancelBtn.disabled = true;
    const orig = submitBtn.textContent;
    submitBtn.textContent = '…';
    try {
      const r = await onSubmit({ host, errEl });
      if (r === false) return;
      close();
    } catch (e) {
      errEl.textContent = isUnlockCancelled(e)
        ? 'Unlock cancelled — nothing was broadcast.'
        : (e?.message || String(e));
    } finally {
      submitBtn.disabled = false; cancelBtn.disabled = false;
      submitBtn.textContent = orig;
    }
  };
  const firstInput = host.querySelector('input, select, textarea');
  if (firstInput) firstInput.focus();
  return { host, errEl, close };
}

if (typeof document !== 'undefined' && !globalThis.__TACIT_NO_INIT__) {
  const _initFarms = async () => {
    try {
      const { initFarmsTab } = await import('./amm-farm-ui.js');
      initFarmsTab();
      const _recBtn = document.getElementById('farms-recover-btn');
      if (_recBtn) {
        _recBtn.onclick = async () => {
          if (!wallet || !wallet.priv) { alert('Unlock a wallet first.'); return; }
          const st = document.getElementById('farms-recover-status');
          const _s = (m) => { if (st) st.textContent = m; };
          _recBtn.disabled = true; const _l = _recBtn.textContent; _recBtn.textContent = 'Scanning…';
          try {
            const r = await farmRecoverPositions({ onProgress: _s });
            _s(r.recovered > 0 ? `Recovered ${r.recovered} farm note${r.recovered === 1 ? '' : 's'} — refresh holdings to spend.` : 'No unsaved farm positions found.');
            try { invalidateHoldingsCache(); } catch {}
          } catch (e) { _s(`Recovery failed: ${e?.message || e}`); }
          finally { _recBtn.disabled = false; _recBtn.textContent = _l; }
        };
      }
    } catch (e) {
      console.warn('[farms] UI module load failed:', e?.message || e);
    }
  };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _initFarms);
  else _initFarms();
}

